contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint amount) public payable {
        require(true);
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory v = new uint[](1);
        v[0] = amount;
        // address(this) accepts any incoming call via fallback, so the
        // low-level transferFrom call made by c always succeeds, no matter
        // how extreme `amount` is. The contract must therefore not revert
        // and must return true even for arbitrary (e.g. huge) amounts.
        bool r = c.transfer(from, address(this), tos, v);
        assert(r == true);
    }
    fallback() external payable {}
    receive() external payable {}
}

