contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external payable {}
    receive() external payable {}

    function run(address from, address[] memory tos, uint[] memory v) public payable {
        bool reverted;
        bool ok;
        if (tos.length == 0) {
            try c.transfer(from, address(this), tos, v) returns (bool r) {
                reverted = false;
                ok = r;
            } catch {
                reverted = true;
                ok = false;
            }
        } else {
            require(v.length == tos.length);
            ok = c.transfer(from, address(this), tos, v);
            reverted = false;
        }
        if (tos.length == 0) {
            assert(reverted);
        } else {
            assert(!reverted && ok);
        }
    }
}

